    \draw[thick] (2.5, 4.5) -- (2.5, 1.5);
    \draw[thick, fill=gray!40] (2, 0.5) rectangle (3, 1.5);
    \node at (2.5, 1) {A};
    \node[right] at (3.2, 1) {$m=200g$};
    \node[above] at (0.75, 5.2) {$V = 6V$};
