\begin{document}
\begin{tikzpicture}[>=latex, font=\sffamily]
    % Diagram 1: Open Circuit
    \begin{scope}[xshift=0cm]
        \draw[thick] (0,3) node[above]{A} -- (0,-1) node[below]{B};
        \draw (0,3) -- (-1.5,3) to[battery1] (-1.5,1) to[nos] (-1.5,-1) -- (0,-1);
        \filldraw[fill=gray!30] (0,1) ellipse (0.8 and 0.3);
        \draw[thick, fill=black] (0,1) -- (0,1.8) -- (0.2,1) cycle; % N pole
        \draw[thick, fill=white] (0,1) -- (0,0.2) -- (-0.2,1) cycle; % S pole
        \node at (0, 2) {N};
        \node at (0, 0) {S};
        \node[above] at (0, 3.5) {ទិសដៅចរន្តអត់មាន};
    \end{scope}

    % Diagram 2: Closed Circuit (Current flows Down)
    \begin{scope}[xshift=5cm]
        \draw[thick, ->] (0,3) node[above]{A} -- (0,1.5);
        \draw[thick] (0,1.5) -- (0,-1) node[below]{B};
        \draw (0,3) -- (-1.5,3) to[battery1] (-1.5,1) to[switch, *-*] (-1.5,-1) -- (0,-1);
        \filldraw[fill=gray!30, rotate around={-30:(0,1)}] (0,1) ellipse (0.8 and 0.3);
        \begin{scope}[rotate around={-30:(0,1)}]
            \draw[thick, fill=black] (0,1) -- (0,1.8) -- (0.2,1) cycle; % N pole
            \draw[thick, fill=white] (0,1) -- (0,0.2) -- (-0.2,1) cycle; % S pole
            \node at (0, 2.1) {N};
            \node at (0, -0.1) {S};
        \end{scope}
        \draw[->, thick, dashed, red] (0,2.5) arc (90:0:0.5);
        \node[right, red] at (0.5, 2.5) {ទិសដៅលំងាក};
    \end{scope}
\end{tikzpicture}
\end{document}

យើងយកខ្សែចម្លងត្រង់មួយ AB ទៅដាក់ក្រោមត្រីវិស័យ ហើយភ្ជាប់ខ្សែចម្លងនោះទៅនឹងសៀគ្វីបិទមួយដូចរូប ។ ពេលយើងចុចកុងតាក់ចរន្តអគ្គិសនីបានឆ្លងកាត់ខ្សែចម្លង AB ពេលនោះយើងឃើញត្រីវិស័យងាកចេញពីស្ថានភាពដើម ហើយលែងវិលខ្សែចម្លង ។ ម្ដងនេះ យើងដាក់ខ្សែចម្លង AB ពីលើត្រីវិស័យវិញម្ដង នៅពេលចរន្តឆ្លងកាត់ខ្សែចម្លង AB យើងសង្កេតឃើញត្រីវិស័យងាកចេញពីស្ថានភាពដើមហើយលែងវិលខ្សែចម្លងដែរ ប៉ុន្តែតាមទិសផ្ទុយពីមុន ។ ម្យ៉ាងវិញទៀតបើយើងប្ដូរទិសដៅចរន្ត ត្រីវិស័យប្ដូរទិសដៅដែរ ។

ពិសោធន៍នេះបញ្ជាក់ឱ្យឃើញថា ក្នុងលំហជុំវិញខ្សែចម្លងឆ្លងកាត់ដោយចរន្តអគ្គិសនី រាប់បង្កើតឱ្យមានដែនម៉ាញេទិចមួយហៅថា ដែនម៉ាញេទិចនៃចរន្តអគ្គិសនី ។ ដែនម៉ាញេទិចនេះធ្វើឱ្យត្រីវិស័យងាកចេញពីស្ថានភាពលំនឹងដើម ។

2.1. ខ្សែដែនឬខ្សែម៉ាញេទិចនៃចរន្តត្រង់

