    \draw[thick] (-3, 1) -- (3, 1) -- (4, 3) -- (-2, 3) cycle; % Cardboard plane

    % Solenoid Coils
    \foreach \x in {-2.5, -2, -1.5, -1, -0.5, 0, 0.5, 1, 1.5, 2, 2.5} {
        \draw[thick, red] (\x, 1.5) ellipse (0.2 and 0.6);
        \filldraw[black] (\x, 2.1) circle (1pt);
