  \node[below] at (5, -1) {គ្រឿងទទួលអគ្គិសនី};
\end{tikzpicture}
\end{document}

ត្រង់ស្វូមានពីរប្រភេទគឺ ត្រង់ស្វូដំឡើងតង់ស្យុង និងត្រង់ស្វូបញ្ចុះតង់ស្យុង។ ត្រង់ស្វូដំឡើងតង់ស្យុងពីទាបទៅខ្ពស់ហៅថា ស៊ួកវ៉ុលទ័រ ។ ឯត្រង់ស្វូបញ្ចុះតង់ស្យុងពីខ្ពស់ទៅទាបហៅថា ស៊ូវ៉ុលទ័រ ។

