\begin{tikzpicture}[scale=0.9]
  % Object AB
  \draw[thick, blue, ->] (-5, -1.5) -- (-5, 1.5) node[above] {វត្ថុ ($h$)};
  \draw[dashed] (-5,0) -- (0,0) node[midway, above] {$d$};

  % Pinhole Barrier (Front of the box)
  \draw[thick, fill=gray!30] (0, 2.5) -- (0, 0.1) (0, -0.1) -- (0, -2.5);
  \fill (0,0) circle (0.06) node[above right] {$O$};

  % Screen (Back of the box)
  \draw[thick, fill=gray!10] (3, 2.5) -- (3, -2.5);
  \draw[dashed] (0,0) -- (3,0) node[midway, above] {$d'$};

  % Image A'B'
  \draw[thick, red, <-] (3, -0.9) node[below] {រូបភាព ($h'$)} -- (3, 0.9);

