sections.body:
កាលណា គេបញ្ចាំងកាំពន្លឺមួយចេញពីចំណុច A ឱ្យប៉ះនិងកញ្ចក់ប្លង់ត្រង់ I (រូប) កាំពន្លឺនោះផ្លាតមកមជ្ឈដ្ឋានដើមវិញតាមទិស IR ។ គេបាន :
\begin{tikzpicture}
  % Draw the mirror
  \draw[thick] (-2, 0) -- (2, 0);
  \draw[fill=gray!20] (-2, -0.5) rectangle (2, 0);

  % Draw the normal
  \draw[dashed, thick] (0, -0.5) -- (0, 2) node[above] {N};

  % Draw the incident ray
  \draw[thick, ->] (-2, 1.5) node[above] {A} -- (-0.2, 0.15);
  \draw[thick] (-0.2, 0.15) -- (0, 0);

  % Draw the reflected ray
  \draw[thick, ->] (0, 0) -- (1.8, 1.35) node[above] {R};

  % Draw the point of incidence
  \node[below right] at (0, 0) {I};

  % Draw the angles
  \draw (0, 0.5) arc (90:143:0.5);
  \node at (-0.3, 0.8) {i};

  \draw (0, 0.5) arc (90:37:0.5);
  \node at (0.3, 0.8) {r};

  % Draw the protractor scale (simplified)
  \draw (0,0) circle (1.8);
  \clip (-2, 0) rectangle (2, 2);
  \foreach \angle in {0, 10, ..., 180} {
    \draw (\angle:1.7) -- (\angle:1.8);
  }
\end{tikzpicture}

កាំ AI ហៅថា កាំប៉ះ ។
កាំ IR ហៅថា កាំផ្លាត ។
ចំណុច I ជាចំណុចចំណាំងប៉ះ ។
ខ្សែ IN កែងនិងកញ្ចក់ត្រង់ចំណុចចំណាំងប៉ះហៅថា ខ្សែក្រែង ។
មុំ i ដែលកើតពីកាំចំណាំងប៉ះ AI និងខ្សែក្រែង N ហៅថា មុំចំណាំងប៉ះ ។
មុំ r ដែលកើតឡើងពីកាំចំណាំងផ្លាត IR និងខ្សែក្រែងហៅថា មុំចំណាំងផ្លាត ។
មុំចំណាំងប៉ះ i ស្មើនឹងមុំចំណាំងផ្លាត r ។

យើងពិនិត្យមើលកញ្ចក់ប្លង់ដែលចាំងចេញពីចំណុច A ហើយចូលទៅក្នុងភ្នែកអ្នកសង្កេតម្នាក់ក្រោយពីតាំងផ្លាតលើផ្ទៃកញ្ចក់មក ។ ភ្នែកអ្នកសង្កេតឃើញចំណុចភ្លឺ A នៅត្រង់ A' ក្រោយកញ្ចក់ ព្រោះបន្ទាយកាំតាំងផ្លាតទាំងអស់ជួបគ្នាត្រង់ A' និង IR ជួបគ្នាត្រង់ A' ។ ភ្នែកអ្នកសង្កេតឃើញពន្លឺទាំងអស់ហាក់ដូចជាចេញមកពីប្រភព A' ។ តាមពិត A' គ្មានទេ គេថា A' ជាចំណុចរូបភាពមិនពិត ។
\begin{tikzpicture}
  % Draw the mirror
  \draw[ultra thick] (0, -2) -- (0, 3) node[above right] {កញ្ចក់ប្លង់};
  \fill[pattern=north east lines] (0, -2) rectangle (0.2, 3);

  % Draw the object point
  \filldraw (-3, 0) circle (2pt) node[left] {A};

  % Draw the image point
  \filldraw (3, 0) circle (2pt) node[right] {A'};

  % Draw the lamp
  \draw[thick] (-3.5, 0.5) -- (-3, 0) -- (-3.5, -0.5);
  \draw[thick] (-3.5, 0.5) .. controls (-3.8, 0.5) and (-3.8, -0.5) .. (-3.5, -0.5);
  \draw[decorate,decoration={coil,segment length=2pt}] (-3.4, 0.3) -- (-3.4, -0.3);

  % Draw light rays from A to mirror
  \draw[thick, ->] (-3, 0) -- (-0.2, 1.5);
  \draw[thick] (-0.2, 1.5) -- (0, 1.6);
  \node[right] at (0, 1.6) {I};

  \draw[thick, ->] (-3, 0) -- (-0.2, -1);
  \draw[thick] (-0.2, -1) -- (0, -1.07);

  % Draw normal at incidence points
  \draw[dashed] (-1, 1.6) -- (1, 1.6);
  \draw[dashed] (-1, -1.07) -- (1, -1.07);

  % Draw reflected rays
  \draw[thick, ->] (0, 1.6) -- (-2, 2.5);
  \draw[thick, ->] (0, -1.07) -- (-2, -2);

  % Draw virtual rays to the image
  \draw[dashed] (0, 1.6) -- (3, 0);
  \draw[dashed] (0, -1.07) -- (3, 0);

  % Draw principal axis
  \draw[dashed] (-4, 0) -- (4, 0);

  % Draw eye
  \begin{scope}[shift={(-2.5, -2.5)}, rotate=30]
    \draw[thick] (0,0) arc (180:360:0.5 and 0.2);
    \draw[thick] (0,0) arc (180:0:0.5 and 0.2);
    \filldraw (0.5, 0) circle (1pt);
  \end{scope}

  % Add text
  \node at (0, -2.5) {រូបភាពឱ្យដោយកញ្ចក់ប្លង់};
\end{tikzpicture}

កាលណាគេដាក់វត្ថុមួយនៅពីមុខកញ្ចក់ប្លង់ វាផ្តល់រូបភាពមិនពិតមួយដែលមានស៊ីមេទ្រីនឹងវត្ថុធៀបនឹងកញ្ចក់នោះ ។
សម្គាល់ : រូបភាពមិនពិតមើលឃើញតែវាមិនដិតនៅលើអេក្រង់ទេ ។ ចំណែកឯរូបភាពពិតវិញមើលឃើញហើយទទួលនៅលើអេក្រង់ ។

បរិទស្សន៍ជាឧបករណ៍សាមញ្ញដែលមានកញ្ចក់ប្លង់ពីរស្របនិងឈមគ្នា M និង M' ដាក់ទ្រេតក្រោមមុំ 45° នៅក្នុងសងខាងបំពង់វែងមួយ ។ កែវភ្នែកសម្លឹងពីមុខកញ្ចក់ M មើលឃើញរូបតាងមួយដែលវត្ថុនៅមុខកញ្ចក់ M' ។
នៅកងទ័ពបរិទស្សន៍ដោយសារវាចំណាំងផ្លាតពីរដងលើកញ្ចក់ប្លង់ពីរ គេអាចមើលឃើញរូបភាពនៅទីឆ្ងាយបាំងបានយ៉ាងច្បាស់ ។
\begin{tikzpicture}
  % Draw the sea and ship
  \fill[cyan!20] (-2, -1) rectangle (3, 0);
  \draw[thick] (-2, 0) -- (3, 0);
  \draw[thick, fill=gray] (-1, 0) -- (0, 0) -- (0.5, 0.3) -- (-0.5, 0.3) -- cycle;
  \draw[thick, fill=gray!50] (-0.3, 0.3) rectangle (0.2, 0.6);

  % Draw submarine and periscope
  \draw[thick, fill=gray!80] (1, -1.5) -- (2.5, -1.5) -- (2.8, -1.2) -- (1.2, -1.2) -- cycle;
  \draw[thick] (2.2, -1.2) -- (2.2, 0.5) -- (2.5, 0.5) -- (2.5, -1.2);

  % Draw mirrors M and M'
  \draw[ultra thick] (2.2, 0.2) -- (2.5, 0.5);
  \node[right] at (2.5, 0.5) {M'};
  \draw[ultra thick] (2.2, -1.2) -- (2.5, -0.9);
  \node[right] at (2.5, -0.9) {M};

  % Draw light ray
  \draw[thick, ->, red] (0, 0.4) -- (2.35, 0.4);
  \draw[thick, ->, red] (2.35, 0.4) -- (2.35, -1.05);
  \draw[thick, ->, red] (2.35, -1.05) -- (3.5, -1.05);

  % Draw observer
  \draw[thick] (3.5, -1) circle (0.2);
  \draw[thick] (3.5, -1.2) -- (3.5, -1.5);
  \draw[thick] (3.5, -1.5) -- (3.2, -1.8);
  \draw[thick] (3.5, -1.5) -- (3.8, -1.8);

  % Add text
  \node at (1, -2) {រូបភាពចំណាំងផ្លាតនៃពន្លឺ};
\end{tikzpicture}

កញ្ចក់ស្វ៊ែ ជាផ្ទៃស្វ៊ែ(កំណាត់ស្វ៊ែឬកន្លឹះស្វ៊ែ) ដែលមានមុខខាងបូជាលោហៈហើយបំផ្លាតពន្លឺបានល្អ ។
កញ្ចក់ស្វ៊ែដែលមានមុខខូងហៅថា កញ្ចក់ស្វ៊ែផត ។ រីឯកញ្ចក់ស្វ៊ែដែលមានមុខប៉ោងហៅថា កញ្ចក់ស្វ៊ែប៉ោង ។
\begin{tikzpicture}
  % Concave Mirror
  \begin{scope}[shift={(0,0)}]
    \draw[thick] (0, 1.5) arc (90:-90:0.5 and 1.5);
    \draw[thick, dashed] (0, 1.5) arc (90:270:0.5 and 1.5);
    \fill[pattern=north east lines] (0, 1.5) arc (90:-90:0.5 and 1.5) -- (0.2, -1.5) arc (-90:90:0.5 and 1.5) -- cycle;
    \draw[dashed] (-2.5, 0) -- (2.5, 0);
    \filldraw (-1.5, 0) circle (1.5pt) node[below] {C};
    \filldraw (0.5, 0) circle (1.5pt) node[below] {O};
    \draw[<->] (-1.5, -0.5) -- (0.5, -0.5) node[midway, below] {R};
    \node at (0, 1.8) {ផ្ទៃប៉ោង};
    \node at (0, -1.8) {ផ្ទៃផត};
    \node at (-1.5, -2.5) {ស្វ៊ែ};
  \end{scope}

  % Convex Mirror definition
  \begin{scope}[shift={(4,0)}]
    \draw[ultra thick] (0, 1.5) arc (60:-60:1.73);
    \draw[dashed] (-2, 0) -- (3, 0);
    \filldraw (0.86, 0) circle (1.5pt) node[above right] {O};
    \filldraw (-1, 0) circle (1.5pt) node[above] {C};
    \node at (0, 2) {អ័ក្សអុបទិច};
    \node at (0, -2.5) {គំនូសតាងកញ្ចក់ស្វ៊ែផត};
  \end{scope}

  % Concave Mirror definition
  \begin{scope}[shift={(9,0)}]
    \draw[ultra thick] (0, 1.5) arc (120:240:1.73);
    \draw[dashed] (-3, 0) -- (2, 0);
    \filldraw (-0.86, 0) circle (1.5pt) node[above left] {O};
    \filldraw (1, 0) circle (1.5pt) node[above] {C};
    \node at (0, -2.5) {គំនូសតាងកញ្ចក់ស្វ៊ែប៉ោង};
  \end{scope}
\end{tikzpicture}

ចំណុច C ជាផ្ចិតកំណោងរបស់កញ្ចក់ស្វ៊ែ
ចំណុច O ជាកំពូលកញ្ចក់ស្វ៊ែ
បន្ទាត់ CO កាត់តាមផ្ចិត C និងកំពូល O ហៅថា អ័ក្សអុបទិចនៃកញ្ចក់ស្វ៊ែ ។
ចម្ងាយ OF ពីកំពូលកញ្ចក់ទៅកំណុំហៅថាចម្ងាយ កំណុំ ។ ចម្ងាយនេះស្មើនឹងពាក់កណ្តាលកាំ OC នៃកញ្ចក់ស្វ៊ែ OF = (1/2) OC ។
\begin{tikzpicture}
  % Concave mirror diagram
  \begin{scope}[shift={(0,0)}]
    \draw[ultra thick] (0, 1.5) arc (150:210:3);
    \draw[dashed] (-1, 0) -- (4, 0);
    \node[above] at (-0.4, 0) {O};
    \filldraw (1.5, 0) circle (1.5pt) node[above] {F};
    \filldraw (3, 0) circle (1.5pt) node[above] {C};
    \node[below] at (1.5, -0.2) {កំណុំ};
    \node[below] at (3, -0.2) {ផ្ចិតស្វ៊ែ};
    \node at (0, 2) {កំពូលស្វ៊ែ};
  \end{scope}

  % Concave mirror reflection
  \begin{scope}[shift={(5,0)}]
    \draw[ultra thick] (0, 1.5) arc (150:210:3);
    \draw[dashed] (-1, 0) -- (4, 0);
    \node[above] at (-0.4, 0) {O};
    \filldraw (1.5, 0) circle (1.5pt) node[above] {F};
    \filldraw (3, 0) circle (1.5pt) node[above] {C};
    \node[above] at (3, 1) {ប្លង់កំណុំ};
    \draw[dashed] (3, 1) -- (3, -1);
    \node[above right] at (3, 0) {កំណុំរង};

    % Incident rays
    \foreach \y in {-1, -0.5, 0.5, 1} {
      \draw[->, thick, red] (4, \y) -- (0.1, \y);
    }

    % Reflected rays
    \draw[->, thick, blue] (-0.1, 1) -- (2, -1);
    \draw[->, thick, blue] (-0.1, 0.5) -- (2.5, -0.5);
    \draw[->, thick, blue] (-0.1, -0.5) -- (2.5, 0.5);
    \draw[->, thick, blue] (-0.1, -1) -- (2, 1);
  \end{scope}

  % Convex mirror reflection
  \begin{scope}[shift={(10,0)}]
    \draw[ultra thick] (0, 1.5) arc (30:-30:3);
    \draw[dashed] (-4, 0) -- (2, 0);
    \node[above] at (0.4, 0) {O};
    \filldraw (-1.5, 0) circle (1.5pt) node[above] {F};
    \filldraw (-3, 0) circle (1.5pt) node[above] {C};
    \node[above] at (-1.5, 1) {ប្លង់កំណុំ};
    \draw[dashed] (-1.5, 1) -- (-1.5, -1);
    \node[above right] at (-1.5, 0) {កំណុំរង};

    % Incident rays
    \foreach \y in {-1, -0.5, 0.5, 1} {
      \draw[->, thick, red] (3, \y) -- (0.1, \y);
    }

    % Reflected rays
    \draw[->, thick, blue] (0.1, 1) -- (2, 2);
    \draw[dashed, blue] (0.1, 1) -- (-1.5, 0);

    \draw[->, thick, blue] (0.1, 0.5) -- (2, 1);
    \draw[dashed, blue] (0.1, 0.5) -- (-1.5, 0);

    \draw[->, thick, blue] (0.1, -0.5) -- (2, -1);
    \draw[dashed, blue] (0.1, -0.5) -- (-1.5, 0);

    \draw[->, thick, blue] (0.1, -1) -- (2, -2);
    \draw[dashed, blue] (0.1, -1) -- (-1.5, 0);
  \end{scope}

  \node at (5, -2.5) {សិក្សាដំណើរពន្លឺចំណាំងផ្លាតកញ្ចក់ស្វ៊ែផត};
\end{tikzpicture}

គេបញ្ចាំងបាច់ពន្លឺស្របទៅលើកញ្ចក់ស្វ៊ែផតមួយដោយឱ្យបាច់ពន្លឺនោះស្របនឹងអ័ក្សអុបទិចរបស់វា ។ គេសង្កេតឃើញកាំតាំងផ្លាតទាំងអស់ ជួបចូលត្រង់ចំណុចមួយនៃអ័ក្សនោះ ។ ចំណុចនេះហៅថាកំណុំ F នៃកញ្ចក់ស្វ៊ែ ។ ប្លង់កែងនឹងអ័ក្សអុបទិចត្រង់កំណុំ F ហៅថាប្លង់កំណុំ ។ ផ្ទុយទៅវិញប្រសិនបើគេដាក់ប្រភពពន្លឺត្រង់កំណុំ F នៃកញ្ចក់ស្វ៊ែ គេសង្កេតឃើញកាំតាំងផ្លាតចេញពីកញ្ចក់នោះជាកាំស្របនឹងអ័ក្សអុបទិច ។

ក. រូបភាពឱ្យដោយកញ្ចក់ស្វ៊ែប៉ោង

កញ្ចក់ស្វ៊ែប៉ោងផ្តល់រូបភាពតែមួយប្រភេទគត់គឺ រូបភាពមិនពិត មានទិសដៅដូចវត្ថុនិងមានទំហំតូចជាងវត្ថុ ។
