ឡង់ទីប៉ោងឬឡង់ទីបង្រួម 

ឡង់ទីផតឬឡង់ទីពង្រីក 

អ័ក្សមេឬអ័ក្សអុបទិច

\begin{tikzpicture}[scale=1]
  % ==========================================
  % Top Row: Physical Lenses Concept
  % ==========================================

  % --- Converging Lenses ---
  \begin{scope}[xshift=0cm]
    % Intersection of two spheres
    \draw[dashed, gray] (0,0) circle (1.2);
    \draw[dashed, gray] (1.5,0) circle (1.2);
    \fill[cyan!20] (0.75, 0.935) arc (51.3:128.7:-1.2) arc (231.3:308.7:-1.2) -- cycle;
    \draw[thick] (0.75, 0.935) arc (51.3:128.7:-1.2);
    \draw[thick] (0.75, -0.935) arc (308.7:231.3:-1.2);

    % Centers and Radii
    \filldraw (0,0) circle (1.5pt) node[below] {$C_1$};
    \filldraw (1.5,0) circle (1.5pt) node[below] {$C_2$};
    \draw[->, >=stealth] (0,0) -- (-0.85, -0.85) node[midway, right] {$R_1$};
    \draw[->, >=stealth] (1.5,0) -- (0.65, 0.85) node[midway, left] {$R_2$};

    % Three types of converging lenses
    \begin{scope}[xshift=3cm, yshift=-0.5cm]
      \filldraw[thick, fill=cyan!10] (0, 1) arc (150:210:2) arc (-30:30:2);
      \filldraw[thick, fill=cyan!10] (1, 1) -- (1, -1) arc (-30:30:2);
      \filldraw[thick, fill=cyan!10] (2, 1) arc (150:210:2) arc (-50:50:1.15);
    \end{scope}

    \node at (2.5, -1.8) {\textbf{ឡង់ទីប៉ោងឬឡង់ទីរួម}};
  \end{scope}

  % --- Diverging Lenses ---
  \begin{scope}[xshift=7cm]
    % Space between two spheres
    \draw[dashed, gray] (0,0) circle (1.2);
    \draw[dashed, gray] (2.8,0) circle (1.2);
    \fill[cyan!20] (1.2, 1) -- (1.6, 1) arc (125:235:1.22) -- (1.2, -1) arc (305:55:1.22) -- cycle;
    \draw[thick] (1.2, 1) arc (55:305:1.22);
    \draw[thick] (1.6, 1) arc (125:235:1.22);
    \draw[thick] (1.2, 1) -- (1.6, 1);
    \draw[thick] (1.2, -1) -- (1.6, -1);

    % Centers and Radii
    \filldraw (0,0) circle (1.5pt) node[below] {$C_1$};
    \filldraw (2.8,0) circle (1.5pt) node[below] {$C_2$};
    \draw[->, >=stealth] (0,0) -- (0, 1.2) node[midway, left] {$R_1$};
    \draw[->, >=stealth] (2.8,0) -- (1.95, -0.85) node[midway, below] {$R_2$};

    % Three types of diverging lenses
    \begin{scope}[xshift=3.5cm, yshift=-0.5cm]
      \filldraw[thick, fill=cyan!10] (0, 1) arc (30:-30:2) -- (-0.6,-1) arc (210:150:2) -- cycle;
      \filldraw[thick, fill=cyan!10] (1.2, 1) arc (150:210:2) -- (1.8, -1) -- (1.8, 1) -- cycle;
      \filldraw[thick, fill=cyan!10] (2.8, 1) arc (130:230:1.3) arc (210:150:2) -- cycle;
    \end{scope}

    \node at (3, -1.8) {\textbf{ឡង់ទីផតឬឡង់ទីព្រែក}};
  \end{scope}

  % ==========================================
  % Bottom Row: Optical Symbols
  % ==========================================
  \begin{scope}[yshift=-4.5cm]

    % --- Converging Lens Symbol ---
    \begin{scope}[xshift=0cm]
      \draw[thick] (-1,0) -- (4,0);
      \node[above] at (3, 0) {អ័ក្សមេអ័ក្សអុបទិច};
      \draw[thick, <->, >=stealth] (1.5,-1.5) -- (1.5,1.5);
      \node[below right] at (1.5, -1.5) {L};

      \filldraw (0,0) circle (1.5pt) node[below] {$C_1$};
      \filldraw (1.5,0) circle (1.5pt) node[below left] {$O$};
      \filldraw (3,0) circle (1.5pt) node[below] {$C_2$};

      \node at (1.5, -2.5) {\textbf{គំនូសបំព្រួញឡង់ទីប៉ោងឬឡង់ទីរួម}};
    \end{scope}

    % --- Diverging Lens Symbol ---
    \begin{scope}[xshift=7cm]
      \draw[thick] (-1,0) -- (4,0);
      \node[above] at (3, 0) {អ័ក្សមេអ័ក្សអុបទិច};

      % Diverging lens symbol >-<
      \draw[thick] (1.5,-1.5) -- (1.5,1.5);
      \draw[thick] (1.3, 1.3) -- (1.5, 1.5) -- (1.7, 1.3);
      \draw[thick] (1.3, -1.3) -- (1.5, -1.5) -- (1.7, -1.3);
      \node[below right] at (1.5, -1.5) {L};

      \filldraw (0,0) circle (1.5pt) node[below] {$C_1$};
      \filldraw (1.5,0) circle (1.5pt) node[below left] {$O$};
      \filldraw (3,0) circle (1.5pt) node[below] {$C_2$};

      \node at (1.5, -2.5) {\textbf{គំនូសបំព្រួញឡង់ទីផតឬឡង់ទីព្រែក}};
    \end{scope}

  \end{scope}
\end{tikzpicture}
